import Foundation

// MARK: - Role-Based Access Control

enum UserRole: Int, Comparable {
    case guest = 0
    case customer = 1
    case merchant = 2
    case admin = 3

    static func < (lhs: UserRole, rhs: UserRole) -> Bool {
        return lhs.rawValue < rhs.rawValue
    }
}

struct User {
    let id: String
    let role: UserRole
    let merchantId: String?
}

// MARK: - Payment Models

class PaymentContext {
    var transactionId: String?
    var amount: Decimal?
    var currency: String?
    var merchantAccount: MerchantAccount?
    var auditTrail: [String] = []

    func recordAudit(_ entry: String) {
        auditTrail.append("[\(Date())] \(entry)")
    }
}

class MerchantAccount {
    let accountId: String
    let routingNumber: String
    let dailyLimit: Decimal
    var currentDailyTotal: Decimal

    init(accountId: String, routingNumber: String, dailyLimit: Decimal, currentDailyTotal: Decimal) {
        self.accountId = accountId
        self.routingNumber = routingNumber
        self.dailyLimit = dailyLimit
        self.currentDailyTotal = currentDailyTotal
    }

    func canProcess(amount: Decimal) -> Bool {
        return (currentDailyTotal + amount) <= dailyLimit
    }
}

// MARK: - Payment Pipeline

protocol PaymentStage {
    func execute(context: PaymentContext, user: User) -> PaymentResult
}

enum PaymentResult {
    case success
    case failure(String)
    case needsEscalation
}

// MARK: - Stage Implementations

class AuthorizationStage: PaymentStage {
    func execute(context: PaymentContext, user: User) -> PaymentResult {
        guard user.role >= .customer else {
            return .failure("Insufficient role for payment processing")
        }
        context.recordAudit("Authorization passed for user \(user.id)")
        return .success
    }
}

class MerchantResolutionStage: PaymentStage {
    private let accountRegistry: [String: MerchantAccount]

    init(accountRegistry: [String: MerchantAccount]) {
        self.accountRegistry = accountRegistry
    }

    func execute(context: PaymentContext, user: User) -> PaymentResult {
        // Admin users can process without merchant binding
        if user.role == .admin {
            context.recordAudit("Admin bypass - no merchant resolution needed")
            return .success
        }

        guard let merchantId = user.merchantId else {
            return .failure("No merchant binding for user")
        }

        // Resolve merchant account from registry
        guard let account = accountRegistry[merchantId] else {
            context.recordAudit("Merchant \(merchantId) not found in registry")
            return .failure("Merchant account not found: \(merchantId)")
        }

        context.merchantAccount = account
        context.recordAudit("Resolved merchant account: \(merchantId)")

        return .success
    }
}

class LimitValidationStage: PaymentStage {
    func execute(context: PaymentContext, user: User) -> PaymentResult {
        guard let amount = context.amount else {
            return .failure("No amount specified")
        }

        // Admin users skip limit checks
        if user.role == .admin {
            context.recordAudit("Admin: limit check skipped")
            return .success
        }

        // For merchant role, check against merchant account limits
        guard let account = context.merchantAccount else {
            return .failure("No merchant account available for limit validation")
        }

        if account.canProcess(amount: amount) {
            context.recordAudit("Limit check passed: \(amount) within daily limit")
            return .success
        } else {
            return .failure("Daily limit exceeded")
        }
    }
}

class SettlementStage: PaymentStage {
    func execute(context: PaymentContext, user: User) -> PaymentResult {
        context.transactionId = UUID().uuidString
        context.recordAudit("Settlement complete: \(context.transactionId!)")
        return .success
    }
}

// MARK: - Payment Processor

class PaymentProcessor {
    private let stages: [PaymentStage]

    init(stages: [PaymentStage]) {
        self.stages = stages
    }

    func processPayment(amount: Decimal, currency: String, user: User) -> PaymentResult {
        // Validate amount before entering the pipeline.
        guard amount > 0 else {
            return .failure("Invalid payment amount: must be greater than zero")
        }

        let context = PaymentContext()
        context.amount = amount
        context.currency = currency

        for stage in stages {
            let result = stage.execute(context: context, user: user)
            switch result {
            case .failure(let msg):
                context.recordAudit("Pipeline failed: \(msg)")
                return .failure(msg)
            case .needsEscalation:
                context.recordAudit("Escalation requested")
                return .needsEscalation
            case .success:
                continue
            }
        }

        return .success
    }
}

// MARK: - Factory

func createPaymentProcessor() -> PaymentProcessor {
    let registry: [String: MerchantAccount] = [
        "MERCH001": MerchantAccount(accountId: "ACC001", routingNumber: "021000021", dailyLimit: 50000, currentDailyTotal: 0),
        "MERCH002": MerchantAccount(accountId: "ACC002", routingNumber: "021000089", dailyLimit: 100000, currentDailyTotal: 45000)
    ]

    let stages: [PaymentStage] = [
        AuthorizationStage(),
        MerchantResolutionStage(accountRegistry: registry),
        LimitValidationStage(),
        SettlementStage()
    ]

    return PaymentProcessor(stages: stages)
}

// Usage - safe: unregistered merchant is caught at resolution stage
let processor = createPaymentProcessor()
let user = User(id: "user123", role: .merchant, merchantId: "MERCH999")
let result = processor.processPayment(amount: 100.0, currency: "USD", user: user)
